#!/usr/bin/env node
/**
 * tests/adversarial-m3.js - Empirical Adversarial Stress Test Harness for Milestone 3
 * 
 * Adversarial Testing Scope:
 * Suite 1: Extreme Angle Cones (60° strict / 85° fallback / 90° pure orthogonal / negative primary)
 * Suite 2: Rapid Key Repeat Stress (50 keys in 200ms, throttle enforcement, queue buildup, ghost focus)
 * Suite 3: Dynamic DOM Changes (deleting focused element, inserting items before/after, container hiding)
 * Suite 4: State Traps, Modals & Asynchronous Robustness
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// -----------------------------------------------------------------------------
// 1. Resolve JSDOM across available environments
// -----------------------------------------------------------------------------
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

// -----------------------------------------------------------------------------
// 2. ANSI Terminal Colors & Reporting Infrastructure
// -----------------------------------------------------------------------------
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failures = [];

async function test(suiteId, testId, description, fn) {
  totalChecks++;
  const label = `[${suiteId}.${testId}] ${description}`;
  try {
    await fn();
    passedChecks++;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label}`);
  } catch (err) {
    failedChecks++;
    failures.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.gray}Error: ${err.message}${C.reset}`);
  }
}

// -----------------------------------------------------------------------------
// 3. Environment & Layout Mock Harness
// -----------------------------------------------------------------------------

function makeRect(left, top, width, height) {
  return {
    left: left,
    top: top,
    width: width,
    height: height,
    right: left + width,
    bottom: top + height,
    x: left,
    y: top
  };
}

function createHarness(initialRoute = 'home') {
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const navPath = path.resolve(__dirname, '../app/js/navigation.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + initialRoute,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  window.__TEST_M3__ = true;

  // Scroll mocks
  window.Element.prototype.scrollIntoView = function (opts) {
    this._lastScrollIntoView = opts || true;
  };
  window.Element.prototype.scrollTo = function (x, y) {
    if (typeof x === 'object') {
      this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
      this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
      this._lastScrollBehavior = x.behavior || 'auto';
    } else {
      this.scrollLeft = x !== undefined ? x : (this.scrollLeft || 0);
      this.scrollTop = y !== undefined ? y : (this.scrollTop || 0);
    }
  };

  // Comprehensive TV Layout mock
  window.Element.prototype.getBoundingClientRect = function () {
    // 1. Dynamic override via data-mock-rect attribute
    const mockAttr = this.getAttribute('data-mock-rect');
    if (mockAttr) {
      try {
        const parsed = JSON.parse(mockAttr);
        // If element or any parent is hidden, return 0 geometry
        let curr = this;
        while (curr) {
          if (curr.style && (curr.style.display === 'none' || curr.style.visibility === 'hidden')) {
            return makeRect(0, 0, 0, 0);
          }
          curr = curr.parentElement;
        }
        return makeRect(parsed.left || 0, parsed.top || 0, parsed.width || 0, parsed.height || 0);
      } catch (e) {}
    }

    // 2. Elements inside non-active views or with display: none have 0 geometry
    const view = this.closest('.view');
    if (view && !view.classList.contains('active')) {
      return makeRect(0, 0, 0, 0);
    }
    if (this.style.display === 'none' || this.style.visibility === 'hidden') {
      return makeRect(0, 0, 0, 0);
    }

    // 3. Known component mappings
    const id = this.id;
    if (id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
    if (id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
    if (id === 'hero-list-btn') return makeRect(433, 460, 140, 56);
    if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (id === 'details-trailer-btn') return makeRect(292, 450, 160, 56);
    if (id === 'player-back-btn') return makeRect(96, 54, 56, 56);
    if (id === 'osd-play-btn') return makeRect(912, 940, 96, 96);
    if (id === 'osd-rewind-btn') return makeRect(840, 940, 56, 56);
    if (id === 'osd-forward-btn') return makeRect(1024, 940, 56, 56);

    if (this.classList.contains('brand-container')) return makeRect(96, 24, 200, 48);
    if (this.classList.contains('nav-pill-item')) {
      const route = this.getAttribute('data-route');
      if (route === 'home') return makeRect(790, 28, 75, 40);
      if (route === 'movies') return makeRect(875, 28, 85, 40);
      if (route === 'series') return makeRect(970, 28, 80, 40);
      if (route === 'search') return makeRect(1060, 28, 80, 40);
    }

    if (this.classList.contains('content-shelf')) {
      const shelfIdx = Array.from(this.parentElement.children).indexOf(this);
      return makeRect(0, 560 + shelfIdx * 400, 1920, 380);
    }

    if (this.classList.contains('card-poster')) {
      const parent = this.parentElement;
      const index = Array.from(parent.children).indexOf(this);
      const grid = this.closest('.content-grid-6col');
      if (grid) {
        const col = index % 6;
        const row = Math.floor(index / 6);
        return makeRect(96 + col * 288, 180 + row * 424, 264, 396);
      }
      const isShelf1 = parent.closest('.content-shelf:nth-of-type(2)') || parent.closest('#shelf-trending');
      const top = isShelf1 ? 680 : 1060;
      return makeRect(96 + index * 244, top, 220, 330);
    }

    return makeRect(96, 100, 100, 40);
  };

  const configCode = fs.readFileSync(configPath, 'utf8');
  const navCode = fs.readFileSync(navPath, 'utf8');
  const appCode = fs.readFileSync(appPath, 'utf8');

  window.eval(configCode);
  window.eval(navCode);
  window.eval(appCode);

  window.CinejoyApp.init();

  return { dom, window, app: window.CinejoyApp, nav: window.SpatialNav };
}

function sendKey(window, key, keyCode) {
  const event = new window.KeyboardEvent('keydown', {
    key: key,
    keyCode: keyCode,
    which: keyCode,
    bubbles: true,
    cancelable: true
  });
  window.dispatchEvent(event);
  return event;
}

// -----------------------------------------------------------------------------
// 4. Test Execution Suites
// -----------------------------------------------------------------------------

async function runAllSuites() {
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}   CINEJOY-WEBOS: MILESTONE 3 EMPIRICAL ADVERSARIAL STRESS SUITE       ${C.reset}`);
  console.log(`${C.bold}${C.cyan}   Extreme Cones, Key Repeat Throttle, Ghost Focus & Dynamic DOM       ${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

  // ===========================================================================
  // SUITE 1: Extreme Directional Angle Cones & Mathematical Boundary Tests
  // ===========================================================================
  console.log(`${C.bold}${C.magenta}▶ SUITE 1: Extreme Directional Angle Cones & Mathematical Boundary Tests${C.reset}`);

  // S1.1: 60° Cone Boundary in ArrowRight Navigation (59.9° Pass 1 vs 60.1° Pass 2)
  await test('S1', '1', '60° Cone Boundary in ArrowRight (59.9° Pass 1 vs 60.1° Pass 2)', () => {
    const { window, nav } = createHarness();
    const activeView = window.document.querySelector('.view.active');
    const sandbox = window.document.createElement('div');
    sandbox.id = 'test-spatial-sandbox';
    activeView.appendChild(sandbox);

    // Origin at (100, 100), size 40x40 -> center (120, 120)
    const origin = window.document.createElement('button');
    origin.id = 'origin';
    origin.setAttribute('data-nav', 'true');
    origin.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 40, height: 40 }));
    sandbox.appendChild(origin);

    // Candidate A: 59.9° (dx = 100 -> dy = 100 * tan(59.9°) = 172.508 -> top = 120 + 172.508 - 20 = 272.508)
    const candA = window.document.createElement('button');
    candA.id = 'cand-59.9';
