    Date.now = () => simTime;

    let movesCount = 0;
    const moveListener = () => { movesCount++; };
    nav.on('navigate', moveListener);

    try {
      // Dispatch 50 keydown events spaced by 4ms
      for (let k = 0; k < 50; k++) {
        simTime += 4;
        sendKey(window, 'ArrowRight', 39);
      }

      // With 60ms throttle interval, 200ms can execute at most floor(200/60) + 1 = 4 moves
      assert(movesCount <= 4, `Expected at most 4 moves in 200ms under 60ms throttle, got ${movesCount}`);
      assert(movesCount >= 2, `Expected at least 2 moves in 200ms, got ${movesCount}`);

      // Verify no queue buildup: after burst finishes, simulate 100ms idle time
      simTime += 100;
      // No asynchronous handlers or delayed executions should fire
      const settledFocus = nav.getCurrentFocus();
      assert.strictEqual(settledFocus.id, `seq-btn-${movesCount}`, 'Focus must match immediate executed moves without queue lag');

      // Verify Ghost Focus: Exactly ONE element has .focused class in the entire DOM
      const focusedElements = window.document.querySelectorAll('.focused');
      assert.strictEqual(focusedElements.length, 1, 'DOM must contain exactly ONE .focused element');
      assert.strictEqual(focusedElements[0], settledFocus, '.focused element in DOM must match nav.getCurrentFocus()');
    } finally {
      Date.now = origNow;
      nav.off('navigate', moveListener);
    }
  });

