    mBtn1.setAttribute('data-nav', 'true');
    mBtn1.setAttribute('data-mock-rect', JSON.stringify({ left: 800, top: 400, width: 120, height: 50 }));
    modal.appendChild(mBtn1);

    const mBtn2 = window.document.createElement('button');
    mBtn2.id = 'modal-btn-2';
    mBtn2.setAttribute('data-nav', 'true');
    mBtn2.setAttribute('data-mock-rect', JSON.stringify({ left: 960, top: 400, width: 120, height: 50 }));
    modal.appendChild(mBtn2);

    // Trap focus inside modal
    nav.trap(modal);
    assert.strictEqual(nav.isTrapped(), true);

    nav.setFocus(mBtn1);
    const candidates = nav.getCandidates();
    assert.strictEqual(candidates.length, 2, 'Candidate discovery while trapped must ONLY yield modal children');
    assert(candidates.includes(mBtn1) && candidates.includes(mBtn2));

    nav.resetThrottle();
    const moved = nav.move('right');
    assert.strictEqual(moved, mBtn2);

    // Attempting to move beyond modal elements must hit dead end
    nav.resetThrottle();
    const boundaryMove = nav.move('right');
    assert.strictEqual(boundaryMove, null, 'Trapped navigation must dead-end at modal boundary rather than escape to page');

    // Untrap
    nav.untrap();
    assert.strictEqual(nav.isTrapped(), false);
    const untrappedCandidates = nav.getCandidates();
    assert(untrappedCandidates.length > 2, 'Untrapped candidate search must restore full page candidate scope');
  });

  // S4.2: Abrupt Deletion of Active Modal Trap Container
  await test('S4', '2', 'Abrupt Deletion of Active Modal Trap Container Without Prior Untrap', () => {
    const { window, nav } = createHarness();
    const activeView = window.document.querySelector('.view.active');

    const modal = window.document.createElement('div');
    modal.id = 'ephemeral-modal';
    activeView.appendChild(modal);

    const mBtn = window.document.createElement('button');
    mBtn.id = 'ephemeral-modal-btn';
    mBtn.setAttribute('data-nav', 'true');
    mBtn.setAttribute('data-mock-rect', JSON.stringify({ left: 800, top: 400, width: 120, height: 50 }));
    modal.appendChild(mBtn);

    nav.trap(modal);
    nav.setFocus(mBtn);

    // Abruptly rip out modal from DOM
    modal.remove();

    // Untrap or navigate: must not crash with TypeError
    nav.untrap();
    nav.resetThrottle();
    assert.doesNotThrow(() => {
      sendKey(window, 'ArrowDown', 40);
    });

    const active = nav.getCurrentFocus();
    assert(active && window.document.body.contains(active), 'Focus must self-heal to page after modal deletion');
  });

  // S4.3: View Focus Memory Integrity Across Rapid Hash Cycling (Home -> Movies -> Series -> Home)
  await test('S4', '3', 'View Focus Memory Integrity Across Rapid Hash Cycling', () => {
    const { window, app, nav } = createHarness();

    // Step 1: On Home view, focus hero-details-btn
    const heroDetails = window.document.getElementById('hero-details-btn');
    nav.setFocus(heroDetails);
    assert.strictEqual(nav.getCurrentFocus(), heroDetails);

    // Step 2: Switch to Movies view and focus second card
    app.switchView('movies');
    const movieCards = window.document.querySelectorAll('#view-movies .card-poster');
    assert(movieCards.length >= 2);
    nav.setFocus(movieCards[1]);
    assert.strictEqual(nav.getCurrentFocus(), movieCards[1]);

    // Step 3: Switch to Series view and focus series filter pill
    app.switchView('series');
    const seriesPills = window.document.querySelectorAll('#view-series .filter-pill');
    assert(seriesPills.length > 0);
    nav.setFocus(seriesPills[0]);
    assert.strictEqual(nav.getCurrentFocus(), seriesPills[0]);

    // Step 4: Rapidly return to Movies -> verify movieCards[1] restored
    app.switchView('movies');
    assert.strictEqual(nav.getCurrentFocus(), movieCards[1], 'Movies view return must restore exact remembered card');

    // Step 5: Rapidly return to Home -> verify heroDetails restored
    app.switchView('home');
    assert.strictEqual(nav.getCurrentFocus(), heroDetails, 'Home view return must restore exact remembered hero button');
  });

  // S4.4: Inactive View Candidates Filtering Immunity
  await test('S4', '4', 'Inactive View Candidates Filtering Immunity', () => {
    const { window, app, nav } = createHarness();
    app.switchView('movies');

    // Active view is movies; series, search, details are inactive
    const seriesView = window.document.getElementById('view-series');
    const allSeriesCards = seriesView.querySelectorAll('[data-nav="true"]');
    assert(allSeriesCards.length > 0, 'Series view has navigable cards');

    // Verify none of the series cards are ever returned by getCandidates()
    const activeCandidates = nav.getCandidates();
    for (let c = 0; c < activeCandidates.length; c++) {
      assert(!seriesView.contains(activeCandidates[c]), 'Inactive view card must never appear in getCandidates()');
      assert.strictEqual(nav.isNavigable(activeCandidates[c]), true, 'Every returned candidate must be navigable');
    }
  });

  // ===========================================================================
  // Summary & Exit Code
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}Adversarial Stress Test Execution Summary:${C.reset}`);
  console.log(`  Total Checks:   ${totalChecks}`);
  console.log(`  Passed Checks:  ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:  ${failedChecks > 0 ? C.red : C.green}${failedChecks}${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

  if (failedChecks > 0) {
    console.error(`${C.red}${C.bold}VERDICT: ${failedChecks} ADVERSARIAL STRESS CHECK(S) FAILED${C.reset}\n`);
    failures.forEach((f, idx) => {
      console.error(`${C.red}[Failure ${idx + 1}] ${f.label}${C.reset}`);
      console.error(`  ${f.error}\n`);
    });
    process.exit(1);
  } else {
    console.log(`${C.green}${C.bold}VERDICT: ALL ${passedChecks} ADVERSARIAL STRESS CHECKS PASSED (100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  }
}

runAllSuites().catch((err) => {
  console.error('Unhandled suite error:', err);
  process.exit(1);
});

