// S3.4: Dynamic Container Hiding (display: none & visibility: hidden exclusions)
await test('S3', '4', 'Dynamic Container Hiding (display: none & visibility: hidden exclusions)', () => {
  const { window, nav } = createHarness();
  const activeView = window.document.querySelector('.view.active');

  const shelf1 = window.document.createElement('div');
  shelf1.id = 'shelf-test-1';
  activeView.appendChild(shelf1);

  const s1Btn = window.document.createElement('button');
  s1Btn.id = 's1-btn';
  s1Btn.setAttribute('data-nav', 'true');
  s1Btn.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 80, height: 40 }));
  shelf1.appendChild(s1Btn);

  const shelf2 = window.document.createElement('div');
  shelf2.id = 'shelf-test-2';
  activeView.appendChild(shelf2);

  const s2Btn = window.document.createElement('button');
  s2Btn.id = 's2-btn';
  s2Btn.setAttribute('data-nav', 'true');
  s2Btn.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 200, width: 80, height: 40 }));
  shelf2.appendChild(s2Btn);

  const shelf3 = window.document.createElement('div');
  shelf3.id = 'shelf-test-3';
  activeView.appendChild(shelf3);

  const s3Btn = window.document.createElement('button');
  s3Btn.id = 's3-btn';
  s3Btn.setAttribute('data-nav', 'true');
  s3Btn.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 300, width: 80, height: 40 }));
  shelf3.appendChild(s3Btn);

  nav.setFocus(s1Btn);

  // 1. Hide shelf 2 via display: none
  shelf2.style.display = 'none';

  nav.resetThrottle();
  const movedDown = nav.move('down');
  assert.strictEqual(movedDown, s3Btn, 'ArrowDown must skip hidden shelf2 (display: none) and directly focus shelf3');

  // 2. Move up from s3: must skip hidden shelf 2 and return to s1Btn
  nav.resetThrottle();
  const movedUp = nav.move('up');
  assert.strictEqual(movedUp, s1Btn, 'ArrowUp from s3 must skip hidden shelf2 and return to s1Btn');

  // 3. Hide shelf 3 via visibility: hidden
  shelf3.style.visibility = 'hidden';
  assert.strictEqual(nav.isNavigable(s3Btn), false, 's3Btn inside visibility:hidden shelf3 must not be navigable');

  nav.resetThrottle();
  const candidates = nav.getCandidates();
  assert(!candidates.includes(s2Btn), 's2Btn (display: none) must not be in candidate list');
  assert(!candidates.includes(s3Btn), 's3Btn (visibility: hidden) must not be in candidate list');
});

