// S4.4: Inactive View Candidates Filtering Immunity
await test('S4', '4', 'Inactive View Candidates Filtering Immunity', () => {
  const { window, app, nav } = createHarness();
  app.switchView('movies');

  // Active view is movies; series, search, details are inactive
  const seriesView = window.document.getElementById('view-series');
  const allSeriesCards = seriesView.querySelectorAll('[data-nav="true"]');
  assert(allSeriesCards.length > 0, 'Series view has navigable cards');

  // Verify none of the series cards are ever returned by getCandidates()
  const activeCandidates = nav.getCandidates();
  for (let c = 0; c < activeCandidates.length; c++) {
    assert(!seriesView.contains(activeCandidates[c]), 'Inactive view card must never appear in getCandidates()');
    assert.strictEqual(nav.isNavigable(activeCandidates[c]), true, 'Every returned candidate must be navigable');
  }
});

// ===========================================================================
// SUITE 5: Deep Stress, Tie-Breaking & Scale Invariants
// ===========================================================================
console.log(`\n${C.bold}${C.magenta}▶ SUITE 5: Deep Stress, Tie-Breaking & Scale Invariants${C.reset}`);

// S5.1: Exact Angle Boundary Inclusions (60.000° Pass 1 & 85.000° Pass 2)
await test('S5', '1', 'Exact Angle Boundary Inclusions (60.000° Pass 1 & 85.000° Pass 2)', () => {
  const { window, nav } = createHarness();
  const activeView = window.document.querySelector('.view.active');
  const sandbox = window.document.createElement('div');
  sandbox.id = 'test-spatial-sandbox';
  activeView.appendChild(sandbox);

  const origin = window.document.createElement('button');
  origin.id = 'exact-origin';
  origin.setAttribute('data-nav', 'true');
  origin.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 40, height: 40 }));
  sandbox.appendChild(origin);

  // Exact 60.000° candidate: dx = 100 -> dy = 100 * tan(60°) = 173.20508...
  const exact60 = window.document.createElement('button');
  exact60.id = 'exact-60';
  exact60.setAttribute('data-nav', 'true');
  exact60.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 120 + 173.20508 - 20, width: 40, height: 40 }));
  sandbox.appendChild(exact60);

  nav.setFocus(origin);
  const chosen60 = nav.findBestCandidate(origin, 'right', [exact60]);
  assert.strictEqual(chosen60, exact60, 'Candidate at exact 60.000° boundary must be accepted in Pass 1');

  // Remove exact60 and test exact 85.000° candidate: dx = 100 -> dy = 100 * tan(85°) = 1143.0052...
  exact60.remove();
  const exact85 = window.document.createElement('button');
  exact85.id = 'exact-85';
  exact85.setAttribute('data-nav', 'true');
  exact85.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 120 + 1143.0052 - 20, width: 40, height: 40 }));
  sandbox.appendChild(exact85);

  const chosen85 = nav.findBestCandidate(origin, 'right', [exact85]);
  assert.strictEqual(chosen85, exact85, 'Candidate at exact 85.000° boundary must be accepted in Pass 2');
});

// S5.2: Deterministic Tie-Breaking Cascade (Equal Score -> Overlap -> Euclidean -> DOM Order)
await test('S5', '2', 'Deterministic Tie-Breaking Cascade (Overlap -> Euclidean -> DOM Order)', () => {
  const { window, nav } = createHarness();
  const activeView = window.document.querySelector('.view.active');
  const sandbox = window.document.createElement('div');
  sandbox.id = 'test-spatial-sandbox';
  activeView.appendChild(sandbox);

  const origin = window.document.createElement('button');
  origin.id = 'tie-origin';
  origin.setAttribute('data-nav', 'true');
  origin.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 60, height: 60 }));
  sandbox.appendChild(origin);

  // Symmetric candidates: candUp and candDown with identical geometry and distance
  // candUp at top=0 (dy=40 above), candDown at top=160 (dy=40 below), both at left=220 (dx=60)
  const candUp = window.document.createElement('button');
  candUp.id = 'tie-cand-up';
  candUp.setAttribute('data-nav', 'true');
  candUp.setAttribute('data-mock-rect', JSON.stringify({ left: 220, top: 0, width: 60, height: 60 }));
  sandbox.appendChild(candUp);

  const candDown = window.document.createElement('button');
  candDown.id = 'tie-cand-down';
  candDown.setAttribute('data-nav', 'true');
  candDown.setAttribute('data-mock-rect', JSON.stringify({ left: 220, top: 160, width: 60, height: 60 }));
  sandbox.appendChild(candDown);

  nav.setFocus(origin);
  const chosen = nav.findBestCandidate(origin, 'right', [candUp, candDown]);
  // Since overlap and euclidean are identical, earlier DOM order (candUp) must win deterministically
  assert.strictEqual(chosen, candUp, 'Identical symmetric score candidates must break tie deterministically via DOM order');
});

// S5.3: Rapid Enter Burst on View Navigation Triggers (20 Rapid Enter keypresses)
await test('S5', '3', 'Rapid Enter Burst on View Navigation Triggers (Idempotent Transitions)', () => {
  const { window, app, nav } = createHarness();
  const heroPlay = window.document.getElementById('hero-play-btn');
  nav.setFocus(heroPlay);

  // Hammer Enter 20 times rapidly on Hero Play Button
  for (let k = 0; k < 20; k++) {
    sendKey(window, 'Enter', 13);
  }

  assert.strictEqual(app.state.currentView, 'player', 'App must transition to player view');
  const focusedList = window.document.querySelectorAll('.focused');
  assert.strictEqual(focusedList.length, 1, 'Only 1 element focused after rapid Enter burst');
});

// S5.4: Hierarchical Back Key Rapid Hammering (20 Rapid Back keypresses)
await test('S5', '4', 'Hierarchical Back Key Rapid Hammering (Clean History Unwind)', () => {
  const { window, app } = createHarness();

  // Navigate: Home -> Movies -> Details -> Player
  app.switchView('movies');
  app.openDetails({ title: 'Adversarial Test Movie', year: '2024' });
  app.switchView('player');
  assert.strictEqual(app.state.currentView, 'player');

  // Hammer webOS Back key (461) 20 times rapidly
  for (let k = 0; k < 20; k++) {
    sendKey(window, 'Back', 461);
  }

  // Must unwind to home view without crashing, throwing, or becoming stuck
  assert.strictEqual(app.state.currentView, 'home', 'Rapid Back key burst must cleanly unwind to Home root view');
  const allFocused = window.document.querySelectorAll('.focused');
  assert.strictEqual(allFocused.length, 1, 'Exactly one element focused after back unwind');
});

// S5.5: Dynamic Navigability Stripping (data-nav="false" & removal on active focus)
await test('S5', '5', 'Dynamic Navigability Stripping (data-nav="false" on active focus)', () => {
  const { window, nav } = createHarness();
  const heroPlay = window.document.getElementById('hero-play-btn');
  const heroDetails = window.document.getElementById('hero-details-btn');
  nav.setFocus(heroPlay);

  // Dynamically strip data-nav
  heroPlay.setAttribute('data-nav', 'false');
  assert.strictEqual(nav.isNavigable(heroPlay), false, 'data-nav="false" must revoke navigability');

  nav.resetThrottle();
  const nextEl = nav.move('right');
  assert.strictEqual(nextEl, heroDetails, 'Move away from data-nav="false" element must succeed');
  assert.strictEqual(nav.getCurrentFocus(), heroDetails);
});

// S5.6: Large Rail Scale Stress (50 Dynamically Injected Cards)
await test('S5', '6', 'Large Rail Scale Stress (50 Dynamically Injected Cards Traversal)', () => {
  const { window, nav } = createHarness();
  const activeView = window.document.querySelector('.view.active');
  const railContainer = window.document.createElement('div');
  railContainer.className = 'shelf-rail';
  activeView.appendChild(railContainer);

  const cards = [];
  for (let i = 0; i < 50; i++) {
    const card = window.document.createElement('div');
    card.className = 'card-poster';
    card.setAttribute('data-nav', 'true');
    card.setAttribute('data-nav-group', 'scale-test-rail');
    card.setAttribute('data-nav-index', String(i));
    card.setAttribute('data-mock-rect', JSON.stringify({ left: 96 + i * 244, top: 700, width: 220, height: 330 }));
    railContainer.appendChild(card);
    cards.push(card);
  }

  nav.setFocus(cards[0]);

  // Step across 10 cards using ArrowRight
  for (let s = 0; s < 10; s++) {
    nav.resetThrottle();
    const nextCard = nav.move('right');
    assert.strictEqual(nextCard, cards[s + 1], `Card step ${s} -> ${s + 1} must match linear sequence`);
  }

  assert.strictEqual(nav.getCurrentFocus(), cards[10]);
  const focusedCount = window.document.querySelectorAll('.focused').length;
  assert.strictEqual(focusedCount, 1, 'Only 1 card focused after 10-step traversal');
});

// S5.7: Active View Complete InnerHTML Wipe Recovery
await test('S5', '7', 'Active View Complete InnerHTML Wipe Recovery', () => {
  const { window, nav } = createHarness();
  const activeView = window.document.querySelector('.view.active');
  const heroPlay = window.document.getElementById('hero-play-btn');
  nav.setFocus(heroPlay);

  // Completely wipe out active view DOM contents
  activeView.innerHTML = '';

  // Verify getCurrentFocus() sanitizes detached element
  assert.strictEqual(nav.getCurrentFocus(), null, 'getCurrentFocus() must return null after view content wipe');

  // Directional move should recover to persistent Header without crashing
  nav.resetThrottle();
  assert.doesNotThrow(() => {
    nav.move('up');
  });

  const recovered = nav.getCurrentFocus();
  assert(recovered !== null, 'Focus must recover to header navigation pill');
  assert(recovered.closest('.app-header'), 'Recovered element must reside within app-header');
  assert(recovered.classList.contains('focused'));
});

